.pdesk{--anatomy-weight:1.05px}
.pdesk .pdesk__stage svg text{pointer-events:none}
.pdesk .pdesk__stage:focus-visible:not([data-pointer]){outline:1px dashed var(--anatomy-lo);outline-offset:6px;border-radius:4px}
.pdesk .iso-line.iso-crease,.pdesk .iso-line.iso-bevel{stroke-width:.7px}
.pdesk .iso-line[data-tone="faint"],.pdesk .iso-line[data-tone="lo"]{stroke-width:.8px}
.pdesk .iso-halo{filter:blur(7px);transform:translate(6px,7px)}
.pdesk .m-pad{--anatomy-paper:var(--pc-pad);--anatomy-face:var(--pc-pad);--anatomy-top:var(--pc-pad-top);--anatomy-shade-0:var(--pc-pad-0);--anatomy-shade-1:var(--pc-pad-1);--anatomy-shade-2:var(--pc-pad-2);--anatomy-shade-3:var(--pc-pad-3)}
.pdesk .m-dark{--anatomy-paper:var(--pc-dark);--anatomy-face:var(--pc-dark);--anatomy-top:var(--pc-dark-top);--anatomy-shade-0:var(--pc-dark-0);--anatomy-shade-1:var(--pc-dark-1);--anatomy-shade-2:var(--pc-dark-2);--anatomy-shade-3:var(--pc-dark-3)}
.pdesk .m-disk{--anatomy-paper:var(--pc-disk);--anatomy-face:var(--pc-disk);--anatomy-top:var(--pc-disk-top);--anatomy-shade-0:var(--pc-disk-0);--anatomy-shade-1:var(--pc-disk-1);--anatomy-shade-2:var(--pc-disk-2);--anatomy-shade-3:var(--pc-disk-3)}
.pdesk .m-shell{--anatomy-paper:var(--pc-shell);--anatomy-face:var(--pc-shell);--anatomy-top:var(--pc-shell-top);--anatomy-shade-0:var(--pc-shell-0);--anatomy-shade-1:var(--pc-shell-1);--anatomy-shade-2:var(--pc-shell-2);--anatomy-shade-3:var(--pc-shell-3)}
.pdesk .pc-glass{fill:var(--pc-glass)}
.pdesk .pc-desk{fill:var(--pc-desk)}
.pdesk .pc-window{fill:var(--pc-window)}
.pdesk .pc-titlebar{fill:var(--pc-titlebar)}
.pdesk .pc-titlebar-fade{fill:url(#pc-title-grad)}
.pdesk .pc-cap{fill:var(--pc-cap)}
.pdesk .pc-icon{stroke-width:.9px}
.pdesk .pc-logo{font:600 12.5px/1 "Product Sans","Google Sans",Arial,Helvetica,sans-serif;letter-spacing:-.02em}
.pdesk .pc-search{fill:var(--pc-search)}
.pdesk .pc-input{fill:var(--pc-input)}
.pdesk .pc-query{fill:var(--pc-ink);font-family:Arial,Helvetica,sans-serif}
.pdesk .pc-caret{fill:var(--pc-ink);animation:pdesk-blink 1.06s steps(1,end) infinite}
.pdesk .pc-glare{fill:none;stroke:var(--pc-glare);stroke-width:1px;stroke-linecap:round}
.pdesk .pc-beam{fill:none;stroke:#e9ecff;stroke-width:1.6px;stroke-linecap:round}
.pdesk .pc-dot{fill:#f2f4ff}
.pdesk .pc-led-blue{fill:#4a6cf0}
.pdesk .pc-led-green{fill:#3ec46d}
.pdesk .pc-led-amber{fill:var(--pc-led-off);transition:fill .08s}
.pdesk .pc-led-amber[data-on]{fill:#f2a33a}
.pdesk .pc-button{fill:var(--pc-button)}
.pdesk .pc-power,.pdesk .pc-key{cursor:pointer}
.pdesk .pc-intel{fill:#2f6fe0}
.pdesk .pc-intel-swoosh{fill:none;stroke:#fff;stroke-width:.5px}
.pdesk .pc-intel-text{fill:#fff;font:700 2.6px/1 Arial,Helvetica,sans-serif}
.pdesk .pc-badge{fill:var(--pc-sticker)}
.pdesk .pc-badge-text{fill:#3b3e4b;font:700 2.2px/1 Arial,Helvetica,sans-serif}
.pdesk .pc-flag-r{fill:#e5483f}
.pdesk .pc-flag-g{fill:#3ab05b}
.pdesk .pc-flag-b{fill:#3a74e8}
.pdesk .pc-flag-y{fill:#f2b928}
.pdesk .pc-grille{fill:var(--pc-grille)}
.pdesk .pc-driver{fill:var(--pc-driver)}
.pdesk .pc-cone{fill:var(--pc-cone)}
.pdesk .pc-cap-dust{fill:var(--pc-dust)}
.pdesk .pc-metal{fill:var(--pc-metal)}
.pdesk .pc-disk-hole{fill:var(--pc-hole)}
.pdesk .pc-label{fill:var(--pc-label)}
.pdesk .pc-pad-badge{fill:var(--pc-pad-badge)}
.pdesk .pc-disc{fill:var(--pc-disc)}
.pdesk .pc-disc-sheen{fill:var(--pc-disc-sheen);opacity:.85}
.pdesk .pc-hub{fill:var(--pc-hub)}
.pdesk .pc-cd-text,.pdesk .pc-cd-small{fill:var(--pc-print);font-family:Arial,Helvetica,sans-serif;letter-spacing:.04em}
.pdesk .pc-key[data-down] .iso-top{fill:var(--anatomy-shade-3)}
@keyframes pdesk-blink{50%{opacity:0}}
@media (prefers-reduced-motion:reduce){.pdesk .pc-caret{animation:none}}
.pdesk .pc-hit{fill:transparent;cursor:pointer}
.pdesk [data-part="cd-case"],.pdesk [data-part="cd-tray"]{cursor:pointer}
.pdesk [data-part="mouse"]{cursor:grab}
.pdesk .pdesk__stage[data-dragging],.pdesk .pdesk__stage[data-dragging] [data-part="mouse"]{cursor:grabbing}
.pdesk .pc-livecable path{fill:none;vector-effect:none;stroke-linecap:butt;stroke-linejoin:round}
.pdesk .pc-cable-o{stroke:var(--anatomy-hi)}
.pdesk .pc-cable-i{stroke:var(--anatomy-shade-2)}
.pdesk .pc-cable-s{stroke:var(--anatomy-top)}
.pdesk .pc-arrow{fill:#fff;stroke:#1d1f27;stroke-width:.35px;vector-effect:none;stroke-linejoin:round}
.pdesk .pc-ibeam{fill:none;stroke:#1d1f27;stroke-width:.45px;vector-effect:none}
.pdesk .pc-slot{fill:var(--pc-glass-off)}
.pdesk .pc-ap-shadow{fill:rgba(20,22,30,.18)}
.pdesk .pc-ap-title{fill:#fff;font:700 2.6px/1 Arial,Helvetica,sans-serif}
.pdesk .pc-ap-head{fill:var(--pc-ink);font:700 3.3px/1 Arial,Helvetica,sans-serif}
.pdesk .pc-ap-body{fill:#5d6070;font:400 2.3px/1 Arial,Helvetica,sans-serif}
.pdesk .pc-ap-disc{fill:#e3e5ec;stroke:#5d6070;stroke-width:.3px;vector-effect:none}
.pdesk .pc-ap-ring{fill:#f6f7fa;stroke:#8a8d99;stroke-width:.25px;vector-effect:none}
.pdesk .pc-ap-hole{fill:#5d6070}
.pdesk .pc-ap-shine{fill:none;stroke:#fff;stroke-width:.8px;vector-effect:none;stroke-linecap:round}
.pdesk .pc-led-cd{fill:var(--pc-led-off);transition:fill .08s}
.pdesk .pc-led-cd[data-on]{fill:#3ec46d}
@keyframes pdesk-in{0%{opacity:0;transform:translateY(-18px)}22%{opacity:1}100%{opacity:1;transform:none}}
@keyframes pdesk-fade{from{opacity:0}}
.pdesk .pdesk--intro .it{animation:pdesk-in .72s cubic-bezier(.2,.9,.28,1.12) backwards;animation-delay:var(--d)}
.pdesk .pdesk--intro .it[data-obj="key"]{animation-duration:.5s}
.pdesk .pdesk--intro .it[data-obj="cable"]{animation:pdesk-fade .32s ease-out backwards;animation-delay:var(--d)}
.pdesk .pdesk--intro .pc-halos{animation:pdesk-fade .9s ease-out backwards .15s}
@media (prefers-reduced-motion:reduce){.pdesk .pdesk--intro .it,.pdesk .pdesk--intro .it[data-obj="cable"],.pdesk .pdesk--intro .pc-halos{animation:none}}
